sys_variable_value.value:
// Create a new GlideRecord object to query the media table.
var gr = new GlideRecord('x_683127_sharkflix_media');

// Use the Action's input values for the query.
gr.addQuery('title', inputs.title);
gr.addQuery('type', inputs.type);
gr.addQuery('release_year', inputs.releaseYear);
gr.addQuery('sys_id', '!=', inputs.sysId);

// Execute the query.
gr.query();

// Set the 'isDuplicate' output to true if a record is found.
if (gr.next()) {
    outputs.isDuplicate = true;
} else {
    outputs.isDuplicate = false;
}

// Set a valid action status object. This is crucial to prevent the "Invalid return type" error.
outputs.action_status = {
    "code": "0",
    "message": "Script executed successfully."
};

